from __future__ import annotations

from pathlib import Path

from build.colors import to_hex
from build.tokens import Tokens

OUTPUT = Path("godot") / "apply_zinc_theme.gd"

# Godot derives the whole editor palette from these. The base is one step lighter than the
# chrome since Godot darkens it for backgrounds, and the rose-400 accent keeps accent-colored
# text readable on that base.
BASE = "surface.raised"
ACCENT = "accent.hover"
CONTRAST = 0.3

TEMPLATE = """\
@tool
extends EditorScript

# Generated by `python -m build godot-theme`. Open it in the script editor and run File > Run.
const SETTINGS = {{
	"interface/theme/style": "Modern",
	"interface/theme/color_preset": "Custom",
	"interface/theme/base_color": Color("{base}"),
	"interface/theme/accent_color": Color("{accent}"),
	"interface/theme/contrast": {contrast},
}}


func _run() -> void:
	var editor_settings := EditorInterface.get_editor_settings()
	for key: String in SETTINGS:
		editor_settings.set_setting(key, SETTINGS[key])
"""


def generate_script(tokens: Tokens) -> str:
    return TEMPLATE.format(
        base=to_hex(tokens.resolve(BASE)),
        accent=to_hex(tokens.resolve(ACCENT)),
        contrast=CONTRAST,
    )


def build_godot_theme(root: Path, tokens: Tokens) -> Path:
    path = root / OUTPUT
    path.parent.mkdir(exist_ok=True)
    path.write_text(generate_script(tokens), encoding="utf-8", newline="\n")
    return path
